import { CsvFileInput } from '@/b2b-quick-order/components/CsvFileInput';
import { QuickOrderDisabledOverlay } from '@/b2b-quick-order/components';
import { useQuickOrderCsvUpload } from '@/b2b-quick-order/hooks/useQuickOrderCsvUpload';
import { QuickOrderCsvUploadProps } from '@/b2b-quick-order/types/quickOrderCsvUpload.types';
import { config } from '@/b2b-quick-order/api/initialize';
import { useText } from '@adobe-commerce/elsie/i18n';
import { classes, Container } from '@adobe-commerce/elsie/lib';

export const QuickOrderCsvUpload: Container<QuickOrderCsvUploadProps> = ({
  className,
  routeSampleCSV,
  onFileUpload,
}) => {
  const isQuickOrderActive = config.getConfig().quickOrderActive;

  const t = useText({
    title: 'QuickOrder.CsvFileInput.title',
    helperText: 'QuickOrder.CsvFileInput.helperText',
    downloadSample: 'QuickOrder.CsvFileInput.downloadSample',
    inputLabel: 'QuickOrder.CsvFileInput.inputLabel',
    selectedFile: 'QuickOrder.CsvFileInput.selectedFile',
    disabledMessage: 'QuickOrder.QuickOrderItem.disabledMessage',
  });

  const {
    handleFileUpload,
    error,
    fileName,
    handleDownloadSample,
    showSampleDownload,
  } = useQuickOrderCsvUpload({
    routeSampleCSV,
    onFileUpload,
  });

  return (
    <div
      className={classes(['b2b-quick-order-quick-order-upload-csv', className])}
      data-testid="quick-order-upload-csv"
    >
      <QuickOrderDisabledOverlay
        isDisabled={!isQuickOrderActive}
        message={t.disabledMessage}
      >
        <CsvFileInput
          t={t}
          onFileUpload={handleFileUpload}
          error={error}
          fileName={fileName}
          onDownloadSample={handleDownloadSample}
          showSampleDownload={showSampleDownload}
        />
      </QuickOrderDisabledOverlay>
    </div>
  );
};
